export const getResendCsvBackfillUrl = (params?: ResendCsvBackfillParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/admin/resend-csv-backfill?${stringifiedParams}` : `/api/admin/resend-csv-backfill`
}

/**
 * Accepts parsed Resend export rows and retroactively advances matched
 * pre-aware contacts to `aware` stage, records an `email_click` activity
 * event (with same-day dedup), and recomputes intent scores.
 * Pass ?dry_run=true to preview matched/skipped/unmatched counts without
 * making any changes.
 * @summary Backfill clicked contacts from Resend CSV/XLSX export
 */
export const resendCsvBackfill = async (resendCsvBackfillBody: ResendCsvBackfillBody,
    params?: ResendCsvBackfillParams, options?: Parameters<typeof customFetch>[1]): Promise<ResendCsvBackfillPreview | ResendCsvBackfillResult> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<ResendCsvBackfillPreview | ResendCsvBackfillResult>(getResendCsvBackfillUrl(params),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(resendCsvBackfillBody)
  }
);}





